    println("Round lasted " + elapsed + " seconds");
}

timer_system.code:
startCountdown(seconds)
{
    level thread runCountdown(seconds);
}

runCountdown(seconds)
{
    level endon("game_ended");
    remaining = seconds;
    while (remaining > 0)
    {
        wait 1;
        remaining--;
        if (remaining <= 10)
        {
            players = getplayers();
            for (i = 0; i < players.size; i++)
                players[i] iprintln(remaining + "...");
        }
    }
    level notify("timer_done");
}

hud_element.code:
createTimerHud()
{
    hud = newHudElem();
    hud.x = 320;
    hud.y = 30;
    hud.alignX = "center";
    hud.alignY = "top";
    hud.horzAlign = "center";
    hud.vertAlign = "top";
    hud.fontScale = 1.5;
    hud.color = (1, 1, 1);
    hud.alpha = 1;
    hud setText("00:00");
    return hud;
}

updateTimerHud(hud, seconds)
{
    minutes = int(seconds / 60);
    secs = seconds % 60;
    timeStr = minutes + ":";
    if (secs < 10) timeStr += "0";
    timeStr += secs;
    hud setText(timeStr);
}

destroyHud(hud)
{
    if (isDefined(hud))
        hud destroy();
}

player_score.code:
initPlayerStats()
{
    if (!isDefined(self.kills))  self.kills  = 0;
    if (!isDefined(self.deaths)) self.deaths = 0;
    if (!isDefined(self.score))  self.score  = 0;
}

addScore(points)
{
    if (!isDefined(self.score)) self.score = 0;
    self.score += points;
    self iprintln("+" + points + " pts");
}

recordKill()
{
    if (!isDefined(self.kills)) self.kills = 0;
    self.kills++;
    self addScore(100);
}

recordDeath()
{
    if (!isDefined(self.deaths)) self.deaths = 0;
    self.deaths++;
}
